        for c in colors:
            xs = [x for x, value in enumerate(row) if value == c]
            if len(xs) < 2:
                continue
            lo, hi = min(xs), max(xs)
            bars.setdefault(r, []).append((lo, hi, c))
            for x in range(lo, hi + 1):
